export const combineInitialState = reducers => {
    
  const globalState = {};

  // set default state returned by reducer and its reducer
  for (const [key, value] of Object.entries(reducers)) {
    
    if (typeof value === "function") {
      globalState[key] = value(undefined, undefined);
    } else {
      console.error(`${value} is not a function`);
    }
    
  }

    var result;
    result = Object.keys(globalState).reduce(function (r, k) {
        return r.concat(globalState[k]);
    }, []);
      
  let merged = Object.assign(...result);

  return merged;
};
